function updateToggleSlider(container){const buttons=container.querySelectorAll('.toggle-btn');if(!buttons.length)return;let sliderEl=container.querySelector('.toggle-slider');if(!sliderEl){sliderEl=document.createElement('div');sliderEl.className='toggle-slider';container.querySelector('.toggle-buttons').prepend(sliderEl);}
const activeBtn=container.querySelector('.toggle-btn.active');if(!activeBtn)return;const btnRect=activeBtn.getBoundingClientRect();const containerRect=container.querySelector('.toggle-buttons').getBoundingClientRect();sliderEl.style.width=btnRect.width+'px';sliderEl.style.transform=`translateX(${
    btnRect.left - containerRect.left
  }px)`;}
document.addEventListener('DOMContentLoaded',()=>{const containers=document.querySelectorAll('.toggle-container');const containerStates=new Map();containers.forEach((container)=>{updateToggleSlider(container);const buttons=container.querySelectorAll('.toggle-btn');const panels=container.querySelectorAll('.toggle-panel');const h1Headers=container.querySelectorAll('.toggle-header > span');if(!buttons.length||!panels.length||!h1Headers.length)return;const canonicalButton=Array.from(buttons).find((b)=>b.dataset.canonical==='true');const canonicalVariant=canonicalButton?canonicalButton.dataset.variant:buttons[0].dataset.variant;const setHeaderId=(header,text,variant)=>{const baseId=text.trim().toLowerCase().replace(/\s+/g,'-').replace(/[^\w\-]/g,'');const isCanonical=variant===canonicalVariant;const fullId=isCanonical?baseId:`${variant}-${baseId}`
header.id=fullId;const link=header.querySelector('a, .headerlink');if(link){link.setAttribute('href',`#${fullId}`);}};panels.forEach((panel)=>{const variant=panel.dataset.variant;const headers=panel.querySelectorAll('h1, h2, h3, h4, h5, h6');headers.forEach((h)=>{const text=Array.from(h.childNodes).filter((n)=>n.nodeType===Node.TEXT_NODE).map((n)=>n.textContent).join('');setHeaderId(h,text,variant);});});h1Headers.forEach((span)=>{const variant=span.dataset.variant;if(!variant)return;const h1=span.querySelector('h1');if(!h1)return;setHeaderId(h1,h1.textContent,variant);});const originalCanonicalTOC=document.querySelector('nav.md-nav.md-nav--secondary')?.outerHTML;function swapTOC(variant){const allSidebars=document.querySelectorAll('nav.md-nav.md-nav--secondary');if(!allSidebars.length){console.error('[toggle] No sidebar found');return;}
if(variant===canonicalVariant){if(originalCanonicalTOC){allSidebars.forEach((sidebar)=>{const temp=document.createElement('div');temp.innerHTML=originalCanonicalTOC;const clone=temp.firstElementChild;if(clone){sidebar.parentNode.replaceChild(clone,sidebar);}});}
return;}
const panel=container.querySelector(`.toggle-panel[data-variant="${variant}"]`);if(!panel||!panel.dataset.tocHtml)return;allSidebars.forEach((sidebar)=>{const temp=document.createElement('div');temp.innerHTML=panel.dataset.tocHtml;const newSidebar=temp.firstElementChild;if(newSidebar){sidebar.parentNode.replaceChild(newSidebar,sidebar);}});}
function getInitialVariant(){const hash=window.location.hash.slice(1);const isValidVariant=[...buttons].some((b)=>b.dataset.variant===hash);if(isValidVariant)return hash;for(const button of buttons){const variant=button.dataset.variant;if(variant!==canonicalVariant&&hash.startsWith(`${variant}-`)){return variant;}}
return canonicalVariant;}
let currentVariant=getInitialVariant();const badgeBlocks=container.querySelectorAll('.page-header-row[data-variant]');function setState(variant,updateUrl=true){currentVariant=variant;buttons.forEach((b)=>b.classList.toggle('active',b.dataset.variant===variant));panels.forEach((p)=>p.classList.toggle('active',p.dataset.variant===variant));h1Headers.forEach((h)=>h.classList.toggle('active',h.dataset.variant===variant));badgeBlocks.forEach((b)=>b.classList.toggle('active',b.dataset.variant===variant));swapTOC(variant);updateToggleSlider(container);if(updateUrl){if(variant===canonicalVariant){history.replaceState(null,'',window.location.pathname);}else{window.location.hash=variant;}}}
setState(currentVariant,false);containerStates.set(container,{setState,getInitialVariant,canonicalVariant});buttons.forEach((btn)=>{btn.addEventListener('click',()=>{setState(btn.dataset.variant);});});});window.addEventListener('hashchange',()=>{containerStates.forEach(({setState,getInitialVariant,canonicalVariant},container)=>{const newVariant=getInitialVariant();const activeBtn=container.querySelector('.toggle-btn.active');const currentVariant=activeBtn?.dataset.variant||canonicalVariant;if(newVariant!==currentVariant){setState(newVariant,false);const hash=window.location.hash.slice(1);if(hash){requestAnimationFrame(()=>{const target=document.getElementById(hash);if(target){target.scrollIntoView({behavior:'smooth',block:'start'});}});}}});});});